import {
  computed,
  defineComponent,
  h,
  inject,
  provide,
  ref,
  watchEffect,
  type Component,
  type InjectionKey,
  type PropType,
} from 'vue';
import { motion } from 'motion-v';

import { useIsInView } from '../../utils/use-is-in-view';
import { Slot } from '../slot';
import {
  SlidingNumber,
  type SlidingNumberProps,
} from '../texts/sliding-number';
import {
  Particles,
  ParticlesEffect,
  type ParticlesEffectProps,
} from '../effects/particles';

type GithubStarsContextType = {
  stars: () => number;
  currentStars: () => number;
  setCurrentStars: (stars: number) => void;
  isCompleted: () => boolean;
  isLoading: () => boolean;
};

const GithubStarsKey: InjectionKey<GithubStarsContextType> = Symbol(
  'AnimateUIGithubStars',
);

function useGithubStars() {
  const context = inject(GithubStarsKey, null);
  if (!context)
    throw new Error('useGithubStars must be used within GithubStars');
  return context;
}

type GithubStarsProps = {
  username?: string;
  repo?: string;
  value?: number;
  delay?: number;
  inView?: boolean;
  inViewMargin?: string;
  inViewOnce?: boolean;
  asChild?: boolean;
};

const elementOf = (node: unknown) => {
  const element = (node as { $el?: unknown } | null)?.$el ?? node;
  if (element instanceof HTMLElement) return element;
  // A child component rendering a fragment: its element follows the anchor.
  const next = element instanceof Node ? element.nextSibling : null;
  return next instanceof HTMLElement ? next : null;
};

/** Loads a repository's stars from GitHub (or takes `value`) and counts up to them. */
const GithubStars = defineComponent({
  name: 'GithubStars',
  inheritAttrs: false,
  props: {
    username: String,
    repo: String,
    value: { type: Number, default: undefined },
    delay: { type: Number, default: 0 },
    inView: Boolean,
    inViewMargin: { type: String, default: '0px' },
    inViewOnce: { type: Boolean, default: true },
    asChild: Boolean,
  },
  setup(props, { attrs, slots }) {
    const { element, isInView } = useIsInView(() => props);
    const stars = ref(props.value ?? 0);
    const currentStars = ref(0);
    const isLoading = ref(true);
    const isCompleted = computed(() => currentStars.value === stars.value);

    watchEffect((onCleanup) => {
      if (props.value !== undefined) {
        stars.value = props.value;
        isLoading.value = false;
        return;
      }
      stars.value = 0;
      isLoading.value = true;
      const { username, repo, delay } = props;
      if (!isInView.value || !username || !repo) return;

      const controller = new AbortController();
      const timeout = setTimeout(() => {
        fetch(`https://api.github.com/repos/${username}/${repo}`, {
          signal: controller.signal,
        })
          .then((response) => {
            if (!response.ok)
              throw new Error(`GitHub API responded ${response.status}`);
            return response.json();
          })
          .then((data) => {
            if (typeof data?.stargazers_count !== 'number')
              throw new Error('GitHub API sent no star count');
            stars.value = data.stargazers_count;
            isLoading.value = false;
          })
          .catch((error) => {
            if (!controller.signal.aborted)
              console.error(
                'Animate UI GithubStars: could not load stars',
                error,
              );
          });
      }, delay);
      onCleanup(() => {
        clearTimeout(timeout);
        controller.abort();
      });
    });

    provide(GithubStarsKey, {
      stars: () => stars.value,
      currentStars: () => currentStars.value,
      setCurrentStars: (value) => (currentStars.value = value),
      isCompleted: () => isCompleted.value,
      isLoading: () => isLoading.value,
    });

    return () => {
      const shared = {
        'aria-busy': isLoading.value || undefined,
        ...attrs,
        ref: (node: unknown) => {
          element.value = elementOf(node);
        },
      };
      return props.asChild
        ? h(
            Slot as Component,
            {
              ...shared,
              style: isLoading.value
                ? [attrs.style, { visibility: 'hidden' }]
                : attrs.style,
            },
            slots,
          )
        : h(motion.div as Component, shared, () =>
            isLoading.value ? null : slots.default?.(),
          );
    };
  },
});

type GithubStarsNumberProps = Omit<SlidingNumberProps, 'number' | 'fromNumber'>;

/** The star count, sliding up from 0. */
const GithubStarsNumber = defineComponent({
  name: 'GithubStarsNumber',
  inheritAttrs: false,
  props: {
    padStart: { type: Boolean, default: true },
  },
  setup(props, { attrs }) {
    const { stars, setCurrentStars } = useGithubStars();
    return () =>
      h(SlidingNumber as Component, {
        number: stars(),
        fromNumber: 0,
        padStart: props.padStart,
        onNumberChange: setCurrentStars,
        ...attrs,
      });
  },
});

type GithubStarsIconProps = {
  icon: Component;
  color?: string;
  activeClass?: string;
};

/** An icon that fills up as the count climbs. */
const GithubStarsIcon = defineComponent({
  name: 'GithubStarsIcon',
  inheritAttrs: false,
  props: {
    icon: { type: [Object, Function] as PropType<Component>, required: true },
    color: { type: String, default: 'currentColor' },
    activeClass: String,
  },
  setup(props, { attrs }) {
    const { stars, currentStars, isCompleted } = useGithubStars();
    return () => {
      const fillPercentage = stars() > 0 ? (currentStars() / stars()) * 100 : 0;
      const { class: className, style, ...rest } = attrs;
      return h('div', { style: { position: 'relative' } }, [
        h(props.icon, {
          'aria-hidden': 'true',
          ...rest,
          class: className,
          style,
        }),
        h(props.icon, {
          'aria-hidden': 'true',
          ...rest,
          class: [className, props.activeClass],
          style: [
            style,
            {
              position: 'absolute',
              top: 0,
              left: 0,
              fill: props.color,
              stroke: props.color,
              clipPath: `inset(${100 - (isCompleted() ? fillPercentage : fillPercentage - 10)}% 0 0 0)`,
            },
          ],
        }),
      ]);
    };
  },
});

type GithubStarsParticlesProps = ParticlesEffectProps & {
  size?: number;
};

/** Bursts particles around its child once the count is reached. */
const GithubStarsParticles = defineComponent({
  name: 'GithubStarsParticles',
  inheritAttrs: false,
  props: {
    size: { type: Number, default: 4 },
  },
  setup(props, { attrs, slots }) {
    const { isCompleted } = useGithubStars();
    return () =>
      h(Particles as Component, { animate: isCompleted() }, () => [
        slots.default?.(),
        h(ParticlesEffect as Component, {
          ...attrs,
          style: [
            {
              backgroundColor: 'currentcolor',
              borderRadius: '50%',
              width: `${props.size}px`,
              height: `${props.size}px`,
            },
            attrs.style,
          ],
        }),
      ]);
  },
});

/** GitHub's logo. */
const GithubStarsLogo = defineComponent({
  name: 'GithubStarsLogo',
  setup() {
    return () =>
      h(
        'svg',
        {
          role: 'img',
          viewBox: '0 0 24 24',
          fill: 'currentColor',
          'aria-label': 'GitHub',
        },
        h('path', {
          d: 'M12 .297c-6.63 0-12 5.373-12 12 0 5.303 3.438 9.8 8.205 11.385.6.113.82-.258.82-.577 0-.285-.01-1.04-.015-2.04-3.338.724-4.042-1.61-4.042-1.61C4.422 18.07 3.633 17.7 3.633 17.7c-1.087-.744.084-.729.084-.729 1.205.084 1.838 1.236 1.838 1.236 1.07 1.835 2.809 1.305 3.495.998.108-.776.417-1.305.76-1.605-2.665-.3-5.466-1.332-5.466-5.93 0-1.31.465-2.38 1.235-3.22-.135-.303-.54-1.523.105-3.176 0 0 1.005-.322 3.3 1.23.96-.267 1.98-.399 3-.405 1.02.006 2.04.138 3 .405 2.28-1.552 3.285-1.23 3.285-1.23.645 1.653.24 2.873.12 3.176.765.84 1.23 1.91 1.23 3.22 0 4.61-2.805 5.625-5.475 5.92.42.36.81 1.096.81 2.22 0 1.606-.015 2.896-.015 3.286 0 .315.21.69.825.57C20.565 22.092 24 17.592 24 12.297c0-6.627-5.373-12-12-12',
        }),
      );
  },
});

export {
  GithubStars,
  GithubStarsNumber,
  GithubStarsIcon,
  GithubStarsParticles,
  GithubStarsLogo,
  useGithubStars,
  type GithubStarsProps,
  type GithubStarsNumberProps,
  type GithubStarsIconProps,
  type GithubStarsParticlesProps,
  type GithubStarsContextType,
};

import { computed, shallowRef, type ComputedRef, type Ref } from 'vue';
import { useInView } from 'motion-v';

interface UseIsInViewOptions {
  inView?: boolean;
  inViewOnce?: boolean;
  inViewMargin?: string;
}

/** Whether the element is in view, or always true when `inView` is off. */
function useIsInView(options: () => UseIsInViewOptions = () => ({})): {
  element: Ref<HTMLElement | null>;
  isInView: ComputedRef<boolean>;
} {
  const element: Ref<HTMLElement | null> = shallowRef(null);
  const { inViewOnce = false, inViewMargin = '0px' } = options();
  const inView = useInView(element, {
    once: inViewOnce,
    margin: inViewMargin as never,
  });
  return {
    element,
    isInView: computed(() => !options().inView || inView.value),
  };
}

export { useIsInView, type UseIsInViewOptions };

import { defineComponent, h, type Component } from 'vue';
import { Motion } from 'motion-v';

/**
 * Renders its child, animated: the child takes the motion props (and the
 * other attributes) given to the Slot.
 */
const Slot = defineComponent({
  name: 'Slot',
  inheritAttrs: false,
  setup(_, { attrs, slots }) {
    return () => h(Motion as Component, { ...attrs, asChild: true }, slots);
  },
});

export { Slot };

import {
  computed,
  defineComponent,
  Fragment,
  h,
  onBeforeUnmount,
  ref,
  watch,
  type Component,
  type PropType,
} from 'vue';
import {
  animate,
  motion,
  motionValue,
  useSpring,
  useTransform,
  type MotionValue,
  type SpringOptions,
  type Transition,
} from 'motion-v';

import { useIsInView } from '../../../utils/use-is-in-view';
import {
  motionTokens,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN } from '../_text';

const ROLLER_TRANSITION: SpringOptions = {
  stiffness: 200,
  damping: 20,
  mass: 0.4,
};

const COUNT_TRANSITION: Transition = {
  ...motionTokens.spring.number,
  restDelta: 0.001,
  restSpeed: 0.01,
};

function intLength(units: number, factor: number) {
  return Math.floor(Math.abs(units) / factor).toString().length;
}

const SlidingNumberDisplay = defineComponent({
  name: 'SlidingNumberDisplay',
  props: {
    position: { type: Object as PropType<MotionValue<number>>, required: true },
    number: { type: Number, required: true },
  },
  setup(props) {
    const transform = useTransform(props.position, (latest: number) => {
      const current = ((latest % 10) + 10) % 10;
      let offset = (10 + props.number - current) % 10;
      if (offset > 5) offset -= 10;
      return `translateY(${offset * 100}%)`;
    });
    return () =>
      h(
        motion.span as Component,
        {
          'data-slot': 'sliding-number-display',
          style: {
            transform,
            position: 'absolute',
            inset: '0',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          },
        },
        () => props.number,
      );
  },
});

const SlidingNumberRoller = defineComponent({
  name: 'SlidingNumberRoller',
  props: {
    units: { type: Object as PropType<MotionValue<number>>, required: true },
    place: { type: Number, required: true },
    reduce: Boolean,
    transition: { type: Object as PropType<SpringOptions>, required: true },
  },
  setup(props) {
    const digitOf = (value: number) =>
      Math.floor(Math.abs(value) / props.place) % 10;
    const position = useSpring(
      digitOf(props.units.getPrevious() ?? props.units.get()),
      props.transition,
    );
    const roll = (value: number) => {
      const digit = digitOf(value);
      if (props.reduce) position.jump(digit);
      else position.set(digit);
    };
    const off = props.units.on('change', roll);
    onBeforeUnmount(off);
    roll(props.units.get());
    return () =>
      h(
        'span',
        {
          'aria-hidden': 'true',
          'data-slot': 'sliding-number-roller',
          style: {
            position: 'relative',
            display: 'inline-block',
            width: '1ch',
            overflowX: 'visible',
            overflowY: 'clip',
            lineHeight: '1',
            fontVariantNumeric: 'tabular-nums',
          },
        },
        [
          h('span', { style: { visibility: 'hidden' } }, '0'),
          ...Array.from({ length: 10 }, (_, i) =>
            h(SlidingNumberDisplay, { key: i, position, number: i }),
          ),
        ],
      );
  },
});

type FormatOptions = {
  decimals: number;
  decimalSeparator: string;
  thousandSeparator?: string;
  padLength: number;
};

function formatNumber(
  value: number,
  { decimals, decimalSeparator, thousandSeparator, padLength }: FormatOptions,
) {
  const fixed = Math.abs(value).toFixed(decimals);
  const sign = value < 0 && Number(fixed) !== 0 ? '-' : '';
  const [intPart = '0', fracPart] = fixed.split('.');
  let int = intPart.padStart(padLength, '0');
  if (thousandSeparator !== undefined) {
    int = int.replace(/\B(?=(\d{3})+(?!\d))/g, thousandSeparator);
  }
  return fracPart
    ? `${sign}${int}${decimalSeparator}${fracPart}`
    : `${sign}${int}`;
}

const slidingNumberProps = {
  number: { type: Number, required: true },
  fromNumber: { type: Number, default: undefined },
  padStart: Boolean,
  decimalSeparator: { type: String, default: '.' },
  decimalPlaces: { type: Number, default: 0 },
  thousandSeparator: String,
  transition: Object as PropType<SpringOptions>,
  delay: { type: Number, default: 0 },
  initiallyStable: Boolean,
  inView: Boolean,
  inViewMargin: { type: String, default: '0px' },
  inViewOnce: { type: Boolean, default: true },
} as const;

type SlidingNumberProps = {
  number: number;
  fromNumber?: number;
  padStart?: boolean;
  decimalSeparator?: string;
  decimalPlaces?: number;
  thousandSeparator?: string;
  transition?: SpringOptions;
  delay?: number;
  initiallyStable?: boolean;
  inView?: boolean;
  inViewMargin?: string;
  inViewOnce?: boolean;
};

const SlidingNumberContent = defineComponent({
  name: 'SlidingNumberContent',
  inheritAttrs: false,
  props: slidingNumberProps,
  emits: ['numberChange'],
  setup(props, { attrs, emit }) {
    const { element, isInView } = useIsInView(() => props);
    const reduce = useShouldReduceMotion();
    const defaultRollerTransition = useTempoTransition(
      () => ROLLER_TRANSITION as Transition,
    );
    const countTransition = useTempoTransition(() => COUNT_TRANSITION);
    const isCounting = () => props.fromNumber !== undefined;
    const factor = () => Math.pow(10, props.decimalPlaces);
    const toUnits = (value: number) => Math.round(value * factor());

    const initialValue = props.initiallyStable
      ? props.number
      : (props.fromNumber ?? 0);
    const value = motionValue(initialValue);
    const units = motionValue(toUnits(initialValue));
    const layout = ref({
      intLength: intLength(toUnits(initialValue), factor()),
      negative: toUnits(initialValue) < 0,
    });

    value.on('change', (latest) => units.set(toUnits(latest)));
    units.on('change', (latest) => {
      const next = {
        intLength: intLength(latest, factor()),
        negative: latest < 0,
      };
      if (
        layout.value.intLength !== next.intLength ||
        layout.value.negative !== next.negative
      )
        layout.value = next;
      emit('numberChange', latest / factor());
    });
    watch(factor, (f) => units.set(Math.round(value.get() * f)));

    watch(
      () =>
        [
          isInView.value,
          props.number,
          props.delay,
          reduce.value,
          props.initiallyStable,
        ] as const,
      ([inView, number, delay, isReduced, stable], _, onCleanup) => {
        if (!inView) {
          if (!isCounting() && !stable) value.jump(0);
          return;
        }
        const timeoutId = setTimeout(
          () => {
            if (isCounting() && !isReduced)
              animate(value, number, countTransition.value);
            else value.jump(number);
          },
          isReduced ? 0 : delay,
        );
        onCleanup(() => clearTimeout(timeoutId));
      },
      { immediate: true },
    );
    onBeforeUnmount(() => value.stop());

    const shownIntLength = computed(() =>
      props.padStart
        ? Math.max(
            Math.floor(Math.abs(props.number)).toString().length,
            layout.value.intLength,
          )
        : layout.value.intLength,
    );

    return () => {
      const decimals = props.decimalPlaces;
      const f = factor();
      const length = shownIntLength.value;
      const intPlaces = Array.from(
        { length },
        (_, i) => Math.pow(10, length - i - 1) * f,
      );
      const decPlaces = Array.from({ length: decimals }, (_, i) =>
        Math.pow(10, decimals - i - 1),
      );
      const rolling = {
        units,
        reduce: reduce.value,
        transition: (props.transition ??
          defaultRollerTransition.value) as SpringOptions,
      };
      return h(
        'span',
        {
          ...attrs,
          ref: element,
          'data-slot': 'sliding-number',
          style: [
            { display: 'inline-flex', alignItems: 'center' },
            attrs.style,
          ],
        },
        [
          h(
            'span',
            { class: 'sr-only', style: VISUALLY_HIDDEN },
            formatNumber(props.number, {
              decimals,
              decimalSeparator: props.decimalSeparator,
              thousandSeparator: props.thousandSeparator,
              padLength: props.padStart ? length : 0,
            }),
          ),
          layout.value.negative
            ? h(
                'span',
                { 'aria-hidden': 'true', style: { marginRight: '0.25rem' } },
                '-',
              )
            : null,
          ...intPlaces.map((place, idx) => {
            const digitsToRight = intPlaces.length - idx - 1;
            const isSeparatorPosition =
              props.thousandSeparator !== undefined &&
              digitsToRight > 0 &&
              digitsToRight % 3 === 0;
            return h(Fragment, { key: `int-${place}` }, [
              h(SlidingNumberRoller, { place, ...rolling }),
              isSeparatorPosition
                ? h('span', { 'aria-hidden': 'true' }, props.thousandSeparator)
                : null,
            ]);
          }),
          decimals > 0
            ? h(Fragment, [
                h('span', { 'aria-hidden': 'true' }, props.decimalSeparator),
                ...decPlaces.map((place) =>
                  h(SlidingNumberRoller, {
                    key: `dec-${place}`,
                    place,
                    ...rolling,
                  }),
                ),
              ])
            : null,
        ],
      );
    };
  },
});

/** A number whose digits roll to their value, each on its own spring. */
const SlidingNumber = defineComponent({
  name: 'SlidingNumber',
  inheritAttrs: false,
  props: slidingNumberProps,
  emits: ['numberChange'],
  setup(props, { attrs, emit }) {
    return () =>
      h(ReducedMotionConfig, { remount: true }, () =>
        h(SlidingNumberContent, {
          ...attrs,
          ...props,
          onNumberChange: (value: number) => emit('numberChange', value),
        }),
      );
  },
});

export { SlidingNumber, type SlidingNumberProps };

import {
  defineComponent,
  h,
  inject,
  provide,
  type Component,
  type InjectionKey,
  type PropType,
} from 'vue';
import { AnimatePresence, motion, type Transition } from 'motion-v';

import { Slot } from '../../slot';
import { useIsInView } from '../../../utils/use-is-in-view';
import {
  ReducedMotionConfig,
  useShouldReduceMotion,
} from '../../../utils/motion';

type Side = 'top' | 'bottom' | 'left' | 'right';
type Align = 'start' | 'center' | 'end';

type ParticlesContextType = {
  animate: () => boolean;
  isInView: () => boolean;
};

const ParticlesKey: InjectionKey<ParticlesContextType> =
  Symbol('AnimateUIParticles');

type ParticlesProps = {
  animate?: boolean;
  asChild?: boolean;
  inView?: boolean;
  inViewMargin?: string;
  inViewOnce?: boolean;
};

const elementOf = (node: unknown) => {
  const element = (node as { $el?: unknown } | null)?.$el ?? node;
  return element instanceof HTMLElement ? element : null;
};

/** Holds the particles: they burst out while `animate` is on. */
const Particles = defineComponent({
  name: 'Particles',
  inheritAttrs: false,
  props: {
    animate: { type: Boolean, default: true },
    asChild: Boolean,
    inView: Boolean,
    inViewMargin: { type: String, default: '0px' },
    inViewOnce: { type: Boolean, default: true },
  },
  setup(props, { attrs, slots }) {
    const { element, isInView } = useIsInView(() => props);
    provide(ParticlesKey, {
      animate: () => props.animate,
      isInView: () => isInView.value,
    });
    return () =>
      h(ReducedMotionConfig, null, () =>
        h(
          (props.asChild ? Slot : motion.div) as Component,
          {
            ...attrs,
            ref: (node: unknown) => {
              element.value = elementOf(node);
            },
            style: [{ position: 'relative' }, attrs.style],
          },
          slots,
        ),
      );
  },
});

type ParticlesEffectProps = {
  side?: Side;
  align?: Align;
  count?: number;
  radius?: number;
  spread?: number;
  duration?: number;
  holdDelay?: number;
  sideOffset?: number;
  alignOffset?: number;
  delay?: number;
  transition?: Transition;
};

/** The particles: they burst out from a side of their parent and fade. */
const ParticlesEffect = defineComponent({
  name: 'ParticlesEffect',
  inheritAttrs: false,
  props: {
    side: { type: String as PropType<Side>, default: 'top' },
    align: { type: String as PropType<Align>, default: 'center' },
    count: { type: Number, default: 6 },
    radius: { type: Number, default: 30 },
    spread: { type: Number, default: 360 },
    duration: { type: Number, default: 0.8 },
    holdDelay: { type: Number, default: 0.05 },
    sideOffset: { type: Number, default: 0 },
    alignOffset: { type: Number, default: 0 },
    delay: { type: Number, default: 0 },
    transition: Object as PropType<Transition>,
  },
  setup(props, { attrs }) {
    const context = inject(ParticlesKey, null);
    if (!context)
      throw new Error('ParticlesEffect must be used within Particles');
    const reduce = useShouldReduceMotion();
    return () => {
      const isVertical = props.side === 'top' || props.side === 'bottom';
      const alignPct =
        props.align === 'start' ? '0%' : props.align === 'end' ? '100%' : '50%';
      const top = isVertical
        ? props.side === 'top'
          ? `calc(0% - ${props.sideOffset}px)`
          : `calc(100% + ${props.sideOffset}px)`
        : `calc(${alignPct} + ${props.alignOffset}px)`;
      const left = isVertical
        ? `calc(${alignPct} + ${props.alignOffset}px)`
        : props.side === 'left'
          ? `calc(0% - ${props.sideOffset}px)`
          : `calc(100% + ${props.sideOffset}px)`;
      const containerStyle = {
        position: 'absolute',
        top,
        left,
        transform: 'translate(-50%, -50%)',
      };
      const fullCircle = props.spread % 360 === 0 && props.spread !== 0;
      const angleStep =
        (props.spread * (Math.PI / 180)) /
